/**
 * Data access. One seam, two sources.
 *
 *   LIVE   — COQL over the logged-in user's OAuth session (inside CRM)
 *   SAMPLE — anonymised real economics from Tranche 77 (standalone / local dev)
 *
 * The widget picks automatically: framed by Zoho ⇒ live, otherwise sample. Force with
 * ?source=sample or ?source=live.
 */

import { coql, customViews, inZoho } from './zoho.js';
import { SAMPLE_DEALS } from './sample-deals.js';
import { loadLiveDeals, loadLiveInvestors, loadLiveTranches, POOL_QUERIES } from './live.js';

export { POOL_QUERIES };

const qs = new URLSearchParams(typeof location !== 'undefined' ? location.search : '');
export const SOURCE = qs.get('source') || (inZoho() ? 'live' : 'sample');
export const isLive = () => SOURCE === 'live';

/* ------------------------------------------------------------------ pools */

/**
 * The three deal pools.
 *
 * PROVISIONAL. These encode Gabe's screen-share description, not verified CRM view
 * criteria. `loadPoolViews()` fetches the real custom views at runtime so we can show
 * what CRM actually thinks — reconciling the two is a question for Gabe.
 *
 * Pools are not naturally disjoint: an M1 Lite is also un-approved and un-purchasable,
 * so it matches "Soon-to-be M1" too. Gabe described Lite as a double filter ("if it's
 * permit and it's an M1, it's an M1 Lite") — permit is what pulls a deal out of the
 * normal flow. Hence MATCH_ORDER tests permit first while POOLS keeps his display order.
 */
export const POOLS = [
  {
    key: 'available',
    label: 'M1 available for purchase',
    hint: 'Fully approved, has a final, flagged available',
    match: (d) => d.Avail_for_Purchase === true && d.__doc !== 'Permit',
  },
  {
    key: 'soon',
    label: 'Soon-to-be M1',
    hint: 'Underwriting complete, NTP not yet approved',
    subdivide: true, // Gabe's two subdivisions: has a final / no final
    match: (d) => d.Stage === 'M1' && !d.__ntp && !d.Avail_for_Purchase && d.__doc !== 'Permit',
  },
  {
    key: 'lite',
    label: 'M1 lite',
    hint: 'Permit rather than signed job card',
    match: (d) => d.Stage === 'M1' && d.__doc === 'Permit',
  },
];

const MATCH_ORDER = ['lite', 'available', 'soon'];

export function poolFor(deal) {
  for (const key of MATCH_ORDER) {
    const p = POOLS.find((x) => x.key === key);
    if (p.match(deal)) return key;
  }
  return null;
}

export const hasFinal = (d) => d.__final === true;

/** What CRM actually has. Read-only reconnaissance — never throws. */
export async function loadPoolViews() {
  if (!isLive()) return [];
  try {
    const views = await customViews('Deals');
    const want = /soon|available for purchase|m1\s*(lite|light)/i;
    return views.filter((v) => want.test(v.name ?? '')).map((v) => ({ id: v.id, name: v.name }));
  } catch (e) {
    console.warn('custom view probe failed', e);
    return [];
  }
}

/* ------------------------------------------------------------------ deals */

/**
 * Every name here was confirmed against the live org by running it in COQL.
 *
 * Deliberately excluded, because they 400 the whole query:
 *   Additional_Pre_Pay   — not a Deals field at all; it was a derived column in the
 *                          tranche Excel export. CRM's Pre_Pay_Amount formula is the
 *                          authority on live records.
 *   Full_Electricity_Price — likewise absent.
 *   Tranche_Number       — INVALID_QUERY live despite appearing in the metadata export.
 *
 * Note `Battery_kW_Size`: the api_name says kW, the field label says kWh. The label is
 * the honest one (13.5, 27, 40.5 are kWh). Do not "correct" the api_name.
 */
const DEAL_FIELDS = [
  'id', 'Deal_Name', 'Customer_State', 'Stage', 'Amount', 'System_Size',
  'Battery_kW_Size', 'Deal_Type',
  'Pre_Pay_Pct_of_Statement_of_Work', 'Pre_Paid_Percentage_of_Bill_of_Sale',
  'Pre_Pay_Amount', 'Bill_of_Sale_Amount', 'Total_Investor_Contribution',
  'Energy_Community_Tax_Eligible', 'Energy_Community_Title',
  'Domestic_Content', 'Tax_Credit_Percentage', 'ITC_Amount',
  'Safe_Harbor_Strategy', 'Energized_Date', 'Begin_Construction_Date',
  'Avail_for_Purchase', 'Permit_Status',
  // Lookup traversal works in COQL — pulls the installer and tranche in one round trip.
  'Account_Name.Account_Name', 'Tranche.Name', 'Tranche.Tranche_Status',
];

/**
 * Records why live mode fell back, so the UI can say so instead of showing a dead page.
 * Being framed by Zoho is not proof the SDK handshake succeeded or that COQL is allowed —
 * separate "the widget loaded" from "the data layer works", because they fail for
 * completely different reasons and the fixes live in different places.
 */
export const fallback = { active: false, reason: null };

export async function loadDeals() {
  if (!isLive()) return structuredClone(SAMPLE_DEALS);
  try {
    const { deals, perPool } = await loadLiveDeals();
    poolCounts.value = perPool;
    if (!deals.length) throw new Error('all three pool queries returned no rows');
    return deals;
  } catch (e) {
    fallback.active = true;
    fallback.reason = e?.message || String(e);
    console.warn('live deal load failed — falling back to sample data', e);
    return structuredClone(SAMPLE_DEALS);
  }
}

/** Per-pool row counts from the last live fetch, surfaced in the Connection panel. */
export const poolCounts = { value: {} };

/* ------------------------------------------------------------------ investors */

/**
 * Investors are CRM Accounts with Account_Type Investor / Financial partner.
 *
 * `bosMultiplier` is the investor's Bill-of-Sale multiplier. Fairtide's is 1.2, derived
 * from 100/100 rows of Tranche 77 (FINDINGS.md §1). Where it lives in CRM is unknown —
 * the Investor_Pricing / Investor_Pricing_Matrix column set has never been read. Until
 * that's resolved the multiplier is configured here, which is exactly the kind of thing
 * Gabe should shoot down on sight.
 */
export const INVESTORS = [
  {
    id: 'ACC-FAIRTIDE-III',
    Account_Name: 'Fairtide Fund III Series 1 LLC',
    bosMultiplier: 1.2,
    real: true,
    note: 'Multiplier 1.2 verified against 100 deals in Tranche 77',
  },
  {
    id: 'ACC-DEMO',
    Account_Name: 'Solar Demo Investments (sample)',
    bosMultiplier: 1.17,
    real: false,
    note: 'Invented — exists only so the margin comparison has a second column',
  },
];

export async function loadInvestors() {
  if (!isLive()) return structuredClone(INVESTORS);
  try {
    const rows = await loadLiveInvestors();
    if (!rows.length) throw new Error('no investor accounts returned');
    return rows.map((r) => {
      const known = INVESTORS.find((i) => i.Account_Name === r.Account_Name);
      return {
        id: String(r.id),
        Account_Name: r.Account_Name,
        Account_Type: r.Account_Type,
        // Deliberately null: no per-investor BoS multiplier has been found anywhere in
        // CRM, and the 1.2 seen in Tranche 77 does NOT generalise (live Amount→BoS
        // ratios run 1.046–1.103). Live deals therefore use CRM's own computed
        // Bill_of_Sale_Amount rather than a multiplier we invented.
        bosMultiplier: null,
        real: true,
        note: known
          ? 'Using CRM-computed Bill of Sale — no stored pricing multiplier found'
          : 'No pricing configured',
      };
    });
  } catch (e) {
    console.warn('investor load failed, using configured list', e);
    return structuredClone(INVESTORS);
  }
}

/* ------------------------------------------------------------------ pricing */

/**
 * Per-investor pricing. Returns null when the investor has no pricing for a deal's
 * state — which means NOT ELIGIBLE, and the UI must say so rather than hide the deal.
 * That null is load-bearing; it's Gabe's stated requirement.
 *
 * SHAPE IS PROVISIONAL. Real Investor_Pricing columns unread. What we do know from
 * Tranche 77: the true pricing key is (Pre_Pay_Pct_of_SOW × Tax_Credit_Percentage),
 * where tax credit comes from the EC/DC rubric — see FINDINGS.md §2.
 */
const STATES_BY_INVESTOR = {
  'ACC-FAIRTIDE-III': ['CA', 'TX', 'AZ', 'CO', 'UT', 'PR'],
  'ACC-DEMO': ['CA', 'TX', 'AZ'],
};

export function priceFor(deal, investor) {
  // Live: no investor pricing matrix has been located in CRM, so we cannot say a deal is
  // ineligible for an investor. Fall back to CRM's own Bill_of_Sale_Amount and treat the
  // deal as priced if CRM priced it. Overstating eligibility is the lesser error here —
  // understating it would silently hide real inventory.
  if (isLive()) {
    return deal.Bill_of_Sale_Amount != null
      ? { bosMultiplier: null, state: deal.Customer_State, source: 'crm' }
      : null;
  }
  const states = STATES_BY_INVESTOR[investor.id];
  if (!states || !states.includes(deal.Customer_State)) return null;
  if (investor.bosMultiplier == null) return null;
  return { bosMultiplier: investor.bosMultiplier, state: deal.Customer_State };
}

export function pricingGaps(deals, investor) {
  const gaps = new Map();
  for (const d of deals) {
    if (priceFor(d, investor)) continue;
    const k = d.Customer_State || '—';
    gaps.set(k, (gaps.get(k) || 0) + 1);
  }
  return [...gaps].map(([state, count]) => ({ state, count }));
}

/* ------------------------------------------------------------------ tranches */

export const RECENT_TRANCHES = [
  { date: '2026-07-14', investor: 'Fairtide III', deals: 100, total: 3_704_000, status: 'Locked' },
  { date: '2026-07-08', investor: 'Fairtide III', deals: 62, total: 2_180_000, status: 'Locked' },
  { date: '2026-07-02', investor: 'Fairtide III', deals: 44, total: 1_505_000, status: 'Open' },
];

export async function loadRecentTranches() {
  if (!isLive()) return structuredClone(RECENT_TRANCHES);
  try {
    const rows = await loadLiveTranches();
    return rows.map((r) => ({
      id: r.id,
      date: String(r.Tranche_Date ?? '').slice(0, 10),
      investor: r.Name,
      deals: null,
      total: null, // no confirmed total field on Tranches; Tranche_Pricing is null on 2026 records
      status: r.Tranche_Status,
    }));
  } catch (e) {
    console.warn('recent tranches failed', e);
    return [];
  }
}
