/**
 * Zoho CRM transport.
 *
 * Pattern lifted from incquet-dev/IQHDM-Task-Execution-widget, which is the proven
 * working widget in this org: CRM widget (plugin-manifest {"service":"CRM"}), registered
 * as a Web Tab with External hosting, talking over the logged-in user's OAuth session.
 * No apikey, no zapikey, no CORS problem, no middleware.
 *
 *   ZOHO.embeddedApp.on("PageLoad", cb) → ZOHO.embeddedApp.init()
 *   ZOHO.CRM.API.coql({select_query})            reads
 *   ZOHO.CRM.CONFIG.getCurrentUser()             identity
 *   ZOHO.CRM.META.getCustomViews({Entity})       the real pool filters, at runtime
 *   ZOHO.CRM.CONNECTION.invoke('iq_crm', {...})  escape hatch: aggregates, v8 endpoints
 *
 * Aggregate COQL (`select COUNT(id) …`) does NOT work through API.coql — Incquet routes
 * it through CONNECTION.invoke against /crm/v6/coql. Same here.
 */

import { traced, note } from './diag.js';

export const CONNECTION = 'iq_crm';

/**
 * The vendored SDK touches `window` at module scope, so it is imported lazily rather
 * than at the top of this file. That keeps calc/data/roles importable from Node (see
 * test.mjs) and means the SDK only loads when we're actually going to talk to Zoho.
 */
let sdkPromise = null;
export function sdk() {
  if (!sdkPromise) sdkPromise = import('./lib/zohocrmsdk.js').then((m) => m.ZOHO);
  return sdkPromise;
}

/** Are we inside a Zoho iframe, or standalone (local dev / GitHub Pages direct hit)? */
export const inZoho = () => {
  if (typeof window === 'undefined') return false;
  try {
    return window.self !== window.top;
  } catch {
    return true; // cross-origin access threw ⇒ we're framed
  }
};

let ready = null;
let diagReady = false;

/** Resolves once Zoho has handed us the page context. Never rejects — see boot(). */
export function whenReady() {
  if (ready) return ready;
  ready = sdk().then(
    (ZOHO) =>
      new Promise((resolve, reject) => {
        // Record exactly what Zoho handed us before touching the SDK, so a failed
        // handshake is diagnosable from the Connection panel rather than the console.
        try {
          const p = Object.fromEntries(new URLSearchParams(location.search));
          note({ params: p, href: location.href });
        } catch { /* non-fatal */ }

        try {
          ZOHO.embeddedApp.on('PageLoad', (data) => {
            diagReady = true;
            note({ sdkReady: true });
            resolve(data ?? {});
          });
          // Throws if serviceOrigin is absent — postMessage rejects an undefined target
          // origin, `new ZSDK` propagates it, and the SDK is left half-constructed.
          ZOHO.embeddedApp.init();
        } catch (e) {
          note({ sdkError: e?.message || String(e) });
          reject(e);
        }
      })
  );
  ready.catch(() => {}); // keep the shared promise from surfacing as unhandled
  return ready;
}

/**
 * True only once Zoho has completed the handshake. Every CRM read is gated on this —
 * calling ZOHO.CRM.* before PageLoad throws an error that reads like a bug in our query
 * when it is really the SDK not being ready.
 */
export function sdkIsReady() {
  return diagReady;
}

/* ------------------------------------------------------------------ reads */

export async function coql(selectQuery) {
  return traced('COQL', selectQuery, async () => {
    if (!diagReady) {
      throw new Error(
        'Zoho SDK handshake never completed — no CRM call can succeed. ' +
          'Check the serviceOrigin param in the Connection panel.'
      );
    }
    const ZOHO = await sdk();
    const resp = await ZOHO.CRM.API.coql({ select_query: selectQuery });
    // Zoho signals query errors in the body as often as by rejecting.
    if (resp?.status === 'error' || resp?.code) {
      throw new Error(resp.message || resp.code || 'COQL error');
    }
    return { rows: resp?.data ?? [], info: resp?.info ?? {} };
  });
}

/**
 * COUNT via the named connection. Returns 0 rather than throwing — a badge that fails
 * to load must never take the page down with it.
 */
export async function coqlCount(selectQuery) {
  try {
    const ZOHO = await sdk();
    const resp = await ZOHO.CRM.CONNECTION.invoke(CONNECTION, {
      method: 'POST',
      url: 'https://www.zohoapis.com/crm/v6/coql',
      parameters: { select_query: selectQuery },
    });
    if (resp?.status === 'success' && resp.details?.status === 'true') {
      return Number(resp.details?.statusMessage?.data?.[0]?.['COUNT(id)']) || 0;
    }
    return 0;
  } catch (e) {
    console.error('coqlCount failed:', selectQuery, e);
    return 0;
  }
}

export async function currentUser() {
  return traced('getCurrentUser', 'CONFIG.getCurrentUser', async () => {
    const ZOHO = await sdk();
    const data = await ZOHO.CRM.CONFIG.getCurrentUser();
    const u = data?.users?.[0] ?? null;
    note({ user: u ? { name: u.full_name, email: u.email, profile: u.profile?.name, role: u.role?.name } : null });
    return u;
  });
}

/** Org identity — proves which CRM we're actually talking to. */
export async function orgInfo() {
  try {
    return await traced('getOrgInfo', 'CONFIG.getOrgInfo', async () => {
      const ZOHO = await sdk();
      const data = await ZOHO.CRM.CONFIG.getOrgInfo();
      const o = data?.org?.[0] ?? data?.data?.[0] ?? null;
      note({ org: o ? { name: o.company_name, id: o.zgid || o.id } : null });
      return o;
    });
  } catch (e) {
    console.warn('org info unavailable', e);
    return null;
  }
}

/**
 * The real filter criteria behind the three deal pools, straight from CRM.
 * We have never confirmed the pool definitions from the export — this reads them at
 * runtime instead of guessing. See FINDINGS.md §5.
 */
export async function customViews(entity = 'Deals') {
  const ZOHO = await sdk();
  const resp = await ZOHO.CRM.META.getCustomViews({ Entity: entity });
  return resp?.custom_views ?? resp?.data?.custom_views ?? [];
}

export async function fields(entity = 'Deals') {
  const ZOHO = await sdk();
  const resp = await ZOHO.CRM.META.getFields({ Entity: entity });
  return resp?.fields ?? resp?.data?.fields ?? [];
}

/* ------------------------------------------------------------------ writes */

/**
 * Every write funnels through here so there is exactly ONE place that can be switched
 * on, and exactly one place to audit.
 *
 * Writes are OFF for the first review build (Trevor, 19 Jul). Reads are live; anything
 * that mutates CRM returns a description of what it *would* do.
 *
 * The lock path in particular is loud: automation.finalizeTranche5 sets
 * Avail_for_Purchase=false on every deal in the tranche, flips Tranche_Status to
 * "Locked", emails three Investor Relations recipients, and snapshots to Tranche_Logs +
 * Deal_Logs. Not something to fire during a demo.
 */
export const WRITES_ENABLED = false;

export async function write(description, fn) {
  if (!WRITES_ENABLED) {
    console.info('[write suppressed]', description);
    return { suppressed: true, description };
  }
  const result = await fn();
  return { suppressed: false, description, result };
}

export async function createTranche(payload) {
  return write(`Create Tranche "${payload.Name}" with ${payload.dealIds.length} deals`, async () =>
    (await sdk()).CRM.API.insertRecord({
      Entity: 'CustomModule8',
      APIData: {
        Name: payload.Name,
        Investor: payload.investorId,
        Tranche_Date: payload.trancheDate,
        Tranche_Status: 'Open',
      },
      Trigger: [],
    })
  );
}

export async function lockTranche(trancheId) {
  return write(
    `Lock tranche ${trancheId} — runs finalizeTranche5: sets Avail_for_Purchase=false on ` +
      `every deal, Tranche_Status="Locked", emails 3 recipients, snapshots to Tranche_Logs`,
    async () =>
      (await sdk()).CRM.FUNCTIONS.execute('finalizeTranche5', {
        arguments: JSON.stringify({ trancheId }),
      })
  );
}
